const should = require("should");

const NR_TEST_UTILS = require("nr-test-utils");

const viewLayoutModulePath = NR_TEST_UTILS.resolve("@node-red/editor-client/src/js/ui/view-layout.js");

/**
 * Parse an SVG path into its list of absolute end points. Only handles the
 * commands generated by view-layout (M, L, C, S, Q, h, v)
 */
function pathPoints(path) {
    const tokens = path.match(/[a-zA-Z]|-?\d*\.?\d+(?:e[-+]?\d+)?/g);
    const points = [];
    let cmd = null;
    let args = [];
    let current = [0, 0];
    const argCount = { M: 2, L: 2, C: 6, S: 4, Q: 4, h: 1, v: 1 };
    tokens.forEach(function(t) {
        if (/[a-zA-Z]/.test(t)) {
            cmd = t;
            args = [];
            return;
        }
        args.push(parseFloat(t));
        if (args.length === argCount[cmd]) {
            if (cmd === "h") {
                current = [current[0] + args[0], current[1]];
            } else if (cmd === "v") {
                current = [current[0], current[1] + args[0]];
            } else {
                current = [args[args.length - 2], args[args.length - 1]];
            }
            points.push({ cmd, point: current, args: args.slice() });
            args = [];
        }
    });
    return points;
}

function commands(path) {
    return (path.match(/[a-zA-Z]/g) || []).join("");
}

function node(id, x, y, opts) {
    return Object.assign({ id, x, y, w: 100, h: 30, outputs: 1 }, opts || {});
}

describe("editor-client/ui/view-layout", function() {
    let layout;

    before(function() {
        global.RED = {};
        delete require.cache[viewLayoutModulePath];
        layout = require(viewLayoutModulePath);
    });

    after(function() {
        delete global.RED;
        delete require.cache[viewLayoutModulePath];
    });

    describe("constants", function() {
        it("defines the layouts and wire styles", function() {
            layout.FLOW_LAYOUTS.should.eql(["LR", "TB", "auto"]);
            layout.WIRE_STYLES.should.eql(["curved", "orthogonal"]);
            layout.LAYOUT_HORIZONTAL.should.equal("LR");
            layout.LAYOUT_VERTICAL.should.equal("TB");
            layout.LAYOUT_AUTO.should.equal("auto");
        });
        it("has opposite directions for every wire direction", function() {
            Object.keys(layout.WIRE_DIRECTIONS).forEach(function(dir) {
                const opposite = layout.OPPOSITE_WIRE_DIRECTION[dir];
                layout.OPPOSITE_WIRE_DIRECTION[opposite].should.equal(dir);
                layout.WIRE_DIRECTIONS[dir][0].should.equal(-layout.WIRE_DIRECTIONS[opposite][0]);
                layout.WIRE_DIRECTIONS[dir][1].should.equal(-layout.WIRE_DIRECTIONS[opposite][1]);
            });
        });
    });

    describe("getPortPosition", function() {
        const OUT = 0;
        const IN = 1;
        it("places horizontal ports on the left and right edges", function() {
            const n = node("n1", 200, 100);
            const input = layout.getPortPosition(n, IN, 0, "LR");
            input.should.containEql({ x: 150, y: 100, dir: "l" });
            const output = layout.getPortPosition(n, OUT, 0, "LR");
            output.should.containEql({ x: 250, y: 100, dir: "r" });
        });
        it("spreads horizontal outputs vertically, centred on the node", function() {
            const n = node("n1", 200, 100, { outputs: 3, h: 45 });
            layout.getPortPosition(n, OUT, 0, "LR").y.should.equal(100 - 13);
            layout.getPortPosition(n, OUT, 1, "LR").y.should.equal(100);
            layout.getPortPosition(n, OUT, 2, "LR").y.should.equal(100 + 13);
        });
        it("places vertical ports on the top and bottom edges", function() {
            const n = node("n1", 200, 100);
            layout.getPortPosition(n, IN, 0, "TB").should.containEql({ x: 200, y: 85, dir: "t" });
            layout.getPortPosition(n, OUT, 0, "TB").should.containEql({ x: 200, y: 115, dir: "b" });
        });
        it("spreads vertical outputs horizontally, centred on the node", function() {
            const n = node("n1", 200, 100, { outputs: 3 });
            layout.getPortPosition(n, OUT, 0, "TB").x.should.equal(200 - layout.PORT_SPACING_VERTICAL);
            layout.getPortPosition(n, OUT, 1, "TB").x.should.equal(200);
            layout.getPortPosition(n, OUT, 2, "TB").x.should.equal(200 + layout.PORT_SPACING_VERTICAL);
        });
        it("treats a node without outputs or a size as a single centred port", function() {
            const junction = { id: "j1", x: 50, y: 60, w: 0, h: 0 };
            layout.getPortPosition(junction, OUT, undefined, "LR").should.containEql({ x: 50, y: 60, dir: "r" });
            layout.getPortPosition(junction, IN, 0, "TB").should.containEql({ x: 50, y: 60, dir: "t" });
            const noSize = { id: "s1", x: 10, y: 20 };
            layout.getPortPosition(noSize, OUT, 0, "LR").should.containEql({ x: 10, y: 20 });
        });
        it("returns the node bounding box, including the status in horizontal layout", function() {
            const n = node("n1", 200, 100, { statusHeight: 14 });
            layout.getPortPosition(n, OUT, 0, "LR").box.should.eql({ x1: 150, y1: 85, x2: 250, y2: 129 });
            // In vertical layout the status is to the side of the node
            layout.getPortPosition(n, OUT, 0, "TB").box.should.eql({ x1: 150, y1: 85, x2: 250, y2: 115 });
        });
    });

    describe("getDragEndPosition", function() {
        it("faces the end of the wire back towards its start", function() {
            layout.getDragEndPosition({ dir: "r" }, 5, 6).should.eql({ x: 5, y: 6, dir: "l" });
            layout.getDragEndPosition({ dir: "l" }, 5, 6).dir.should.equal("r");
            layout.getDragEndPosition({ dir: "b" }, 5, 6).dir.should.equal("t");
            layout.getDragEndPosition({ dir: "t" }, 5, 6).dir.should.equal("b");
        });
    });

    describe("transposePath", function() {
        it("swaps x and y coordinates of point commands", function() {
            layout.transposePath("M 1 2 C 3 4 5 6 7 8").should.equal("M 2 1 C 4 3 6 5 8 7");
        });
        it("swaps relative horizontal and vertical lines", function() {
            layout.transposePath("M 1 2 h 10 v -5").should.equal("M 2 1 v 10 h -5");
        });
        it("handles negative and decimal values", function() {
            layout.transposePath("M -1.5 2.25 S .5 -3 4 5").should.equal("M 2.25 -1.5 S -3 .5 5 4");
        });
        it("is its own inverse", function() {
            const path = layout.generateLinkPath(0, 0, -100, 4, 1, true);
            const twice = layout.transposePath(layout.transposePath(path));
            pathPoints(twice).should.eql(pathPoints(path));
        });
    });

    describe("generateWirePath - curved", function() {
        it("uses the classic curve for horizontal wires", function() {
            const start = { x: 0, y: 0, dir: "r" };
            const end = { x: 200, y: 50, dir: "l" };
            layout.generateWirePath(start, end, false).should.equal(layout.generateLinkPath(0, 0, 200, 50, 1, false));
            layout.generateWirePath(start, end, false, "curved").should.equal("M 0 0 C 75 0 125 50 200 50");
        });
        it("uses the classic curve for wires dragged from an input", function() {
            const start = { x: 200, y: 50, dir: "l" };
            const end = { x: 0, y: 0, dir: "r" };
            layout.generateWirePath(start, end, true).should.equal(layout.generateLinkPath(200, 50, 0, 0, -1, true));
        });
        it("passes the status flag to the classic curve", function() {
            const start = { x: 0, y: 0, dir: "r" };
            const end = { x: -200, y: 0, dir: "l" };
            layout.generateWirePath(start, end, true).should.equal(layout.generateLinkPath(0, 0, -200, 0, 1, true));
            layout.generateWirePath(start, end, true).should.not.equal(layout.generateWirePath(start, end, false));
        });
        it("uses the transposed classic curve for downward vertical wires", function() {
            const start = { x: 10, y: 0, dir: "b" };
            const end = { x: 60, y: 200, dir: "t" };
            const path = layout.generateWirePath(start, end, false);
            path.should.equal(layout.transposePath(layout.generateLinkPath(0, 10, 200, 60, 1, false)));
            const points = pathPoints(path);
            points[0].point.should.eql([10, 0]);
            points[points.length - 1].point.should.eql([60, 200]);
            // The curve leaves the output downwards
            points[1].args[0].should.equal(10);
            points[1].args[1].should.be.above(0);
        });
        it("uses the transposed classic curve for upward wires dragged from an input", function() {
            const start = { x: 60, y: 200, dir: "t" };
            const end = { x: 10, y: 0, dir: "b" };
            layout.generateWirePath(start, end, false).should.equal(layout.transposePath(layout.generateLinkPath(200, 60, 0, 10, -1, false)));
        });
        it("routes backward vertical wires around the nodes", function() {
            const start = { x: 100, y: 300, dir: "b", box: { x1: 50, y1: 270, x2: 150, y2: 300 } };
            const end = { x: 100, y: 100, dir: "t", box: { x1: 50, y1: 100, x2: 150, y2: 130 } };
            const path = layout.generateWirePath(start, end, false);
            commands(path).should.match(/^M(LQ)+L$/);
            const xs = pathPoints(path).map(p => p.point[0]);
            Math.max.apply(null, xs).should.be.above(150);
        });
        it("uses a bezier between perpendicular ports facing each other", function() {
            const start = { x: 0, y: 0, dir: "r" };
            const end = { x: 200, y: 200, dir: "t" };
            const path = layout.generateWirePath(start, end, false);
            commands(path).should.equal("MC");
            const c = pathPoints(path)[1].args;
            // First control point is to the right of the start
            c[0].should.be.above(0);
            c[1].should.equal(0);
            // Second control point is above the end
            c[2].should.equal(200);
            c[3].should.be.below(200);
        });
        it("routes perpendicular ports facing away from each other around the nodes", function() {
            const start = { x: 100, y: 300, dir: "b" };
            const end = { x: 50, y: 100, dir: "l" };
            const path = layout.generateWirePath(start, end, false);
            commands(path).should.match(/^M(LQ)+L$/);
        });
        it("starts and ends at the ports for every combination of directions", function() {
            const dirs = ["r", "l", "t", "b"];
            const ends = [[300, 200], [-300, 200], [300, -200], [-300, -200], [0, 5], [5, 0]];
            dirs.forEach(function(sd) {
                dirs.forEach(function(ed) {
                    ends.forEach(function(e) {
                        ["curved", "orthogonal"].forEach(function(style) {
                            const path = layout.generateWirePath({ x: 0, y: 0, dir: sd }, { x: e[0], y: e[1], dir: ed }, false, style);
                            path.should.not.match(/NaN|undefined/);
                            const points = pathPoints(path);
                            points[0].point.should.eql([0, 0]);
                            points[points.length - 1].point[0].should.be.approximately(e[0], 0.001);
                            points[points.length - 1].point[1].should.be.approximately(e[1], 0.001);
                        });
                    });
                });
            });
        });
    });

    describe("generateWirePath - orthogonal", function() {
        function cornerPoints(path) {
            // With a zero corner radius, the end points form the polyline
            // (each corner appears three times - before, at and after the corner)
            return pathPoints(path).map(p => p.point).filter(function(p, i, all) {
                return i === 0 || p[0] !== all[i - 1][0] || p[1] !== all[i - 1][1];
            });
        }
        function assertAxisAligned(points) {
            for (let i = 1; i < points.length; i++) {
                const sameX = Math.abs(points[i][0] - points[i - 1][0]) < 0.001;
                const sameY = Math.abs(points[i][1] - points[i - 1][1]) < 0.001;
                (sameX || sameY).should.be.true("segment " + (i - 1) + " is not horizontal or vertical");
            }
        }
        it("only draws straight and rounded segments", function() {
            const path = layout.generateWirePath({ x: 0, y: 0, dir: "r" }, { x: 200, y: 80, dir: "l" }, false, "orthogonal");
            commands(path).should.match(/^M(LQ)*L$/);
        });
        it("routes forward horizontal wires through the midpoint", function() {
            const points = cornerPoints(layout.generateOrthogonalPath({ x: 0, y: 0, dir: "r" }, { x: 200, y: 80, dir: "l" }, false, 0));
            assertAxisAligned(points);
            points.should.containEql([100, 0]);
            points.should.containEql([100, 80]);
        });
        it("routes forward vertical wires through the midpoint", function() {
            const points = cornerPoints(layout.generateOrthogonalPath({ x: 0, y: 0, dir: "b" }, { x: 80, y: 200, dir: "t" }, false, 0));
            assertAxisAligned(points);
            points.should.containEql([0, 100]);
            points.should.containEql([80, 100]);
        });
        it("draws a straight line between aligned ports", function() {
            const path = layout.generateOrthogonalPath({ x: 0, y: 0, dir: "r" }, { x: 200, y: 0, dir: "l" }, false, 8);
            path.should.equal("M 0 0 L 200 0");
        });
        it("routes backward wires below overlapping nodes", function() {
            const start = { x: 250, y: 100, dir: "r", box: { x1: 150, y1: 85, x2: 250, y2: 115 } };
            const end = { x: 0, y: 100, dir: "l", box: { x1: 0, y1: 85, x2: 100, y2: 115 } };
            const points = cornerPoints(layout.generateOrthogonalPath(start, end, false, 0));
            assertAxisAligned(points);
            // Leaves to the right, goes under both nodes and enters from the left
            points[1].should.eql([265, 100]);
            points.should.containEql([265, 135]);
            points.should.containEql([-15, 135]);
            points[points.length - 2].should.eql([-15, 100]);
        });
        it("adds space for the status when routing below nodes", function() {
            const start = { x: 250, y: 100, dir: "r", box: { x1: 150, y1: 85, x2: 250, y2: 115 } };
            const end = { x: 0, y: 100, dir: "l", box: { x1: 0, y1: 85, x2: 100, y2: 115 } };
            const points = cornerPoints(layout.generateOrthogonalPath(start, end, true, 0));
            points.should.containEql([265, 145]);
        });
        it("routes backward wires through the gap between separated nodes", function() {
            const start = { x: 250, y: 100, dir: "r", box: { x1: 150, y1: 85, x2: 250, y2: 115 } };
            const end = { x: 0, y: 300, dir: "l", box: { x1: 0, y1: 285, x2: 100, y2: 315 } };
            const points = cornerPoints(layout.generateOrthogonalPath(start, end, false, 0));
            assertAxisAligned(points);
            points.should.containEql([265, 200]);
            points.should.containEql([-15, 200]);
        });
        it("uses a single corner between perpendicular ports when possible", function() {
            const points = cornerPoints(layout.generateOrthogonalPath({ x: 0, y: 0, dir: "r" }, { x: 200, y: 200, dir: "t" }, false, 0));
            assertAxisAligned(points);
            points.should.eql([[0, 0], [200, 0], [200, 200]]);
        });
        it("goes around when the perpendicular corner is behind a port", function() {
            const points = cornerPoints(layout.generateOrthogonalPath({ x: 0, y: 300, dir: "b" }, { x: 100, y: 0, dir: "l" }, false, 0));
            assertAxisAligned(points);
            points.should.eql([[0, 300], [0, 315], [85, 315], [85, 0], [100, 0]]);
        });
        it("keeps the corner radius within the segment lengths", function() {
            const path = layout.generateOrthogonalPath({ x: 0, y: 0, dir: "r" }, { x: 200, y: 6, dir: "l" }, false, 8);
            // The vertical segment is 6 long, so each corner can only use 3
            path.should.equal("M 0 0 L 97 0 Q 100 0 100 3 L 100 3 Q 100 6 103 6 L 200 6");
        });
    });

    describe("generateRoundedPolylinePath", function() {
        it("removes duplicate and collinear points", function() {
            layout.generateRoundedPolylinePath([[0, 0], [0, 0], [10, 0], [20, 0], [20, 10]], 0)
                .should.equal("M 0 0 L 20 0 Q 20 0 20 0 L 20 10");
        });
        it("rounds corners with the requested radius", function() {
            layout.generateRoundedPolylinePath([[0, 0], [100, 0], [100, 100]], 10)
                .should.equal("M 0 0 L 90 0 Q 100 0 100 10 L 100 100");
        });
    });

    describe("getWireDetour", function() {
        it("uses the middle of the gap between the boxes", function() {
            const start = { x: 0, y: 0, box: { x1: 0, y1: 0, x2: 10, y2: 100 } };
            const end = { x: 0, y: 300, box: { x1: 0, y1: 200, x2: 10, y2: 300 } };
            layout.getWireDetour(start, end, 1, false).should.equal(150);
            layout.getWireDetour(end, start, 1, false).should.equal(150);
        });
        it("goes beyond overlapping boxes", function() {
            const start = { x: 0, y: 0, box: { x1: 0, y1: 0, x2: 100, y2: 30 } };
            const end = { x: 0, y: 0, box: { x1: 50, y1: 10, x2: 180, y2: 40 } };
            layout.getWireDetour(start, end, 0, false).should.equal(200);
            layout.getWireDetour(start, end, 1, false).should.equal(60);
            layout.getWireDetour(start, end, 1, true).should.equal(70);
        });
        it("falls back to the port positions without boxes", function() {
            layout.getWireDetour({ x: 0, y: 0 }, { x: 0, y: 200 }, 1, false).should.equal(100);
            layout.getWireDetour({ x: 0, y: 0 }, { x: 0, y: 10 }, 1, false).should.equal(30);
            layout.getWireDetour({ x: 0, y: 0, box: { y2: 15 } }, { x: 0, y: 10 }, 1, false).should.equal(35);
        });
    });

    describe("getNodeSize", function() {
        const labelParts = { width: 40, lines: ["label"] };
        const def = { inputs: 1 };
        it("sizes a horizontal node as before", function() {
            layout.getNodeSize({ outputs: 1, _def: def }, labelParts, false, "LR").should.eql([100, 30]);
            layout.getNodeSize({ outputs: 4, _def: def }, labelParts, false, "LR").should.eql([100, 60]);
            layout.getNodeSize({ outputs: 4, _def: def }, labelParts, true, "LR").should.eql([30, 60]);
            layout.getNodeSize({ outputs: 1, _def: def }, { width: 200, lines: ["a", "b"] }, false, "LR").should.eql([260, 54]);
        });
        it("grows a vertical node's width, not height, with its outputs", function() {
            layout.getNodeSize({ outputs: 1, _def: def }, labelParts, false, "TB").should.eql([100, 30]);
            layout.getNodeSize({ outputs: 4, _def: def }, labelParts, false, "TB").should.eql([100, 30]);
            layout.getNodeSize({ outputs: 8, _def: def }, labelParts, false, "TB").should.eql([160, 30]);
            layout.getNodeSize({ outputs: 4, _def: def }, labelParts, true, "TB").should.eql([80, 30]);
            layout.getNodeSize({ outputs: 0, _def: def }, labelParts, true, "TB").should.eql([30, 30]);
        });
        it("fits all vertical output ports within the node", function() {
            for (let outputs = 1; outputs < 20; outputs++) {
                const size = layout.getNodeSize({ outputs, _def: def }, labelParts, true, "TB");
                const n = { x: 0, y: 0, w: size[0], h: size[1], outputs };
                const first = layout.getPortPosition(n, 0, 0, "TB");
                const last = layout.getPortPosition(n, 0, outputs - 1, "TB");
                (first.x - 5).should.not.be.below(-size[0] / 2);
                (last.x + 5).should.not.be.above(size[0] / 2);
            }
        });
    });

    describe("computeAutoOrientations", function() {
        const a = node("a", 0, 0);
        const b = node("b", 0, 200);
        const c = node("c", 300, 0);
        const d = node("d", 300, 50);
        it("makes nodes joined by a mostly vertical wire vertical", function() {
            layout.computeAutoOrientations([{ source: a, target: b }]).should.eql({ a: "TB", b: "TB" });
        });
        it("leaves nodes joined by a mostly horizontal wire horizontal", function() {
            layout.computeAutoOrientations([{ source: a, target: c }, { source: c, target: d }].slice(0, 1)).should.eql({});
            layout.computeAutoOrientations([{ source: c, target: d }]).should.eql({ c: "TB", d: "TB" });
        });
        it("uses the majority of a node's wires", function() {
            // a has two horizontal wires and one vertical
            const result = layout.computeAutoOrientations([
                { source: a, target: b },
                { source: a, target: c },
                { source: a, target: node("e", 400, 10) }
            ]);
            should.not.exist(result.a);
            result.b.should.equal("TB");
        });
        it("prefers horizontal on a tie", function() {
            const result = layout.computeAutoOrientations([{ source: a, target: b }, { source: a, target: c }]);
            should.not.exist(result.a);
        });
        it("ignores virtual link node wires", function() {
            layout.computeAutoOrientations([{ source: a, target: b, link: true }]).should.eql({});
        });
    });
    describe("addUnknownOption", function() {
        const options = [{ val: "LR", text: "lr" }, { val: "TB", text: "tb" }];
        const label = function(v) { return "unknown " + v };
        it("adds an option for an unknown value", function() {
            layout.addUnknownOption(options, "XY", label).should.eql([
                { val: "LR", text: "lr" }, { val: "TB", text: "tb" }, { val: "XY", text: "unknown XY" }
            ]);
        });
        it("adds an option for a non-string value", function() {
            layout.addUnknownOption(options, 5, label).should.eql([
                { val: "LR", text: "lr" }, { val: "TB", text: "tb" }, { val: "5", text: "unknown 5" }
            ]);
        });
        it("does not add an option for a known or unset value", function() {
            layout.addUnknownOption(options, "TB", label).should.eql(options);
            layout.addUnknownOption(options, undefined, label).should.eql(options);
            layout.addUnknownOption(options, "", label).should.eql(options);
        });
        it("does not modify the options", function() {
            layout.addUnknownOption(options, "XY", label);
            options.should.have.length(2);
        });
    });

    describe("getPersistedFlowOptions", function() {
        it("stores nothing for a flow using the default layout and wire style", function() {
            layout.getPersistedFlowOptions({ id: "f1" }, {}).should.eql({});
            layout.getPersistedFlowOptions({ id: "f1" }).should.eql({});
            layout.getPersistedFlowOptions({ id: "f1" }, { "view-flow-layout": "LR", "view-wire-style": "curved" }).should.eql({});
        });
        it("stores the editor default layout when it is not the default", function() {
            layout.getPersistedFlowOptions({ id: "f1" }, { "view-flow-layout": "TB" }).should.eql({ layout: "TB" });
            layout.getPersistedFlowOptions({ id: "f1" }, { "view-flow-layout": "auto" }).should.eql({ layout: "auto" });
        });
        it("stores the editor default wire style when it is not the default", function() {
            layout.getPersistedFlowOptions({ id: "f1" }, { "view-wire-style": "orthogonal" }).should.eql({ wireStyle: "orthogonal" });
            layout.getPersistedFlowOptions({ id: "f1" }, { "view-flow-layout": "TB", "view-wire-style": "orthogonal" })
                .should.eql({ layout: "TB", wireStyle: "orthogonal" });
        });
        it("keeps the values set on the flow", function() {
            const settings = { "view-flow-layout": "TB", "view-wire-style": "orthogonal" };
            layout.getPersistedFlowOptions({ id: "f1", layout: "LR", wireStyle: "curved" }, settings)
                .should.eql({ layout: "LR", wireStyle: "curved" });
            layout.getPersistedFlowOptions({ id: "f1", layout: "auto" }, settings)
                .should.eql({ layout: "auto", wireStyle: "orthogonal" });
            layout.getPersistedFlowOptions({ id: "f1", layout: "TB", wireStyle: "orthogonal" }, {})
                .should.eql({ layout: "TB", wireStyle: "orthogonal" });
        });
        it("keeps an unknown value set on the flow", function() {
            layout.getPersistedFlowOptions({ id: "f1", layout: "XY", wireStyle: "zigzag" }, { "view-flow-layout": "TB" })
                .should.eql({ layout: "XY", wireStyle: "zigzag" });
        });
        it("ignores unknown editor default values", function() {
            layout.getPersistedFlowOptions({ id: "f1" }, { "view-flow-layout": "XY", "view-wire-style": "zigzag" }).should.eql({});
        });
        it("does not modify the flow", function() {
            const flow = { id: "f1" };
            layout.getPersistedFlowOptions(flow, { "view-flow-layout": "TB" });
            flow.should.eql({ id: "f1" });
        });
    });
});
